<?php namespace App\Console\Commands; use App\Models\User; use Illuminate\Console\Command; use Illuminate\Support\Facades\{DB,File,Hash}; class LegacyMigrateUsersCommand extends Command {protected $signature='legacy:migrate-users {--ids=} {--dry-run} {--apply} {--out=docs/generated/users-migration-sample}'; public function handle():int{$ids=array_filter(array_map('intval',explode(',',(string)$this->option('ids'))));if(!$ids||($this->option('dry-run')&&$this->option('apply'))){$this->error('Use explicit --ids and one mode.');return 1;}$r=['mode'=>$this->option('apply')?'apply':'dry-run','items'=>[]];foreach(DB::connection('legacy_wp')->table('users')->whereIn('ID',$ids)->orderBy('ID')->get() as $x){$role='user';$caps=DB::connection('legacy_wp')->table('usermeta')->where('user_id',$x->ID)->where('meta_key','tp_capabilities')->value('meta_value');if(is_array($v=@unserialize($caps,['allowed_classes'=>false]))&&($v['administrator']??false))$role='user';$item=['legacy_wp_user_id'=>$x->ID,'role'=>$role,'email_present'=>$x->user_email!=='','password_strategy'=>'laravel_temporary_hash_must_change','anomalies'=>$x->user_email===''?['missing_email']:[]];if($this->option('apply')&&$x->user_email!=='')User::updateOrCreate(['legacy_wp_user_id'=>$x->ID],['name'=>trim($x->display_name)?:'Utilisateur','email'=>$x->user_email,'password'=>Hash::make(env('LEGACY_MIGRATION_TEMP_PASSWORD')),'role'=>$role,'status'=>'active','must_change_password'=>true,'created_at'=>$x->user_registered]);$r['items'][]=$item;}$b=base_path($this->option('out'));File::put($b.'.json',json_encode($r,JSON_PRETTY_PRINT));File::put($b.'.md','# Users migration pilot\n\n```json\n'.json_encode($r,JSON_PRETTY_PRINT).'\n```\n');return 0;}}
